    concatStringsSep "\n" (
      [ header ]
      ++ lib.filter (line: line != "") (map (name: sshDirectiveStr name settings.${name}) orderedNames)
      ++ optional (extraOptions != { }) (
        lib.generators.toKeyValue {
          mkKeyValue = lib.generators.mkKeyValueDefault { } " ";
          listsAsDuplicateKeys = true;
          indent = "  ";
        } extraOptions
      )
    );

  legacyBlockSettings =
    cf:
    let
